1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, evaluate the
3	// precondition (THE only place it is ever evaluated), then on a go run prework and
4	// either converge (agentless) or hand off to an agent session; on a no-go roll a
5	// scheduled item to its next anchor with the reason on record.
6	//
7	// An executor's whole interface is issue read/write plus the repo at HEAD, which
8	// is what makes it platform-agnostic: the reference deployment is a job in the
9	// vendored workflows (the tick's post-tick drain, and a `labeled`-event run for
10	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
11	// enumerates executors; identity is self-declared in the claim comment.
12	//
13	// The pure decisions live at the top and test with fixtures; the shell below is
14	// the GitHub/prework/invocation I/O around them.
15	
16	import { pathToFileURL } from 'node:url';
17	import { nextAnchor } from './anchors.mjs';
18	import {
19	  READY, URGENT, EXECUTING, AGENT, BLOCKED, NEEDS_HUMAN, ORIGIN_SCHEDULE,
20	  OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE, QUEUE_LABELS,
21	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
22	  parseWorkItemTitle, parseWorkItemBody, withNotBefore, withSection, hasLabel,
23	} from './work-item.mjs';
24	
25	// How many items one executor run may take before it stops. Small on purpose: an
26	// executor is code iterating a queue, and more capacity is more executors, not a
27	// longer loop (DESIGN §10).
28	export const DEFAULT_MAX_ITEMS = 3;
29	
30	const titleOf = (item) => (item.title ?? '').trim();
31	const taskIdOf = (item) => {
32	  const p = parseWorkItemTitle(item.title);
33	  return p ? `${p.pack}/${p.task}` : null;
34	};
35	
36	// The pick order (DESIGN §6.1): urgent first, then oldest-created, with two skip
37	// rules read live at pick time.
38	//
39	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
40	//    item executing or handed to an agent — one task, one execution at a time,
41	//    while a fan-out's distinct qualifiers still parallelize.
42	//  - THE `after` YIELD (S24): skip a scheduled item whose task declares `after:
43	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
44	//    A rolled upstream (blocked until its next anchor: it declined this cycle)
45	//    does not block, and neither does one sitting `needs-human` — a broken
46	//    upstream must not halt its dependents indefinitely. Deliberately NOT a
47	//    `Blocked-by` edge: a standing item that rolls never closes, so blocked-by
48	//    would starve every dependent of a quiet upstream forever.
49	//
50	// `open` is every open work item; `taskAfter(id)` gives a task's declared
51	// upstreams as `<pack>/<task>` ids.
52	export function pickOrder(open = [], { taskAfter = () => [] } = {}) {
53	  const live = (item) => hasLabel(item, READY) || hasLabel(item, EXECUTING) || hasLabel(item, AGENT);
54	  const liveUpstream = (upstreamId) => open.some((o) =>
55	    taskIdOf(o) === upstreamId && hasLabel(o, ORIGIN_SCHEDULE) && live(o));
56	
57	  return open
58	    .filter((i) => hasLabel(i, READY) && !hasLabel(i, NEEDS_HUMAN))
59	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
60	      && (hasLabel(o, EXECUTING) || hasLabel(o, AGENT))))
61	    .filter((i) => {
62	      if (!hasLabel(i, ORIGIN_SCHEDULE)) return true;
63	      return !taskAfter(taskIdOf(i)).some(liveUpstream);
64	    })
65	    .sort((a, b) =>
66	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
67	      || new Date(a.created_at) - new Date(b.created_at)
68	      || a.number - b.number);
69	}
70	
71	// The claim comment carries WHO and WHEN — the executor id and its run URL —
72	// because executor identity is an unbounded set and must never become a label
73	// (DESIGN §4).
74	export const claimComment = ({ executor, runUrl, at }) =>
75	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
76	
77	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
78	// each an implicit assumption made explicit:
79	//
80	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
81	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
82	//    comment ids are server-assigned and strictly increasing — a total order the
83	//    protocol gets for free. Nothing here compares runner clocks.
84	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
85	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
86	//    and revert leaves one), and arbitrating over all of them makes a dead claim
87	//    outrank every future live claimant — the item then livelocks through reclaim
88	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
89	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
90	//    owner; it can only leave an item with no state label, which the janitor
91	//    repairs.
92	export function claimWinner(comments = []) {
93	  const sorted = [...comments].sort((a, b) => a.id - b.id);
94	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
95	  const claims = sorted
96	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
97	    .filter((c) => !boundary || c.id > boundary.id);
98	  return claims[0] ?? null;
99	}
100	
101	// After WINNING a claim, re-verify the pick filters against live state (F15). The
102	// filters read possibly-stale state, so two executors can pass them simultaneously
103	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
104	// an upstream and its dependent. The per-item lease cannot see that: it protects
105	// one item, not one title. If a conflicting item now holds an EARLIER claim
106	// (comment id — the same arbiter the lease trusts), this executor reverts its own
107	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
108	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [] } = {}) {
109	  const upstreams = hasLabel(item, ORIGIN_SCHEDULE) ? taskAfter(taskIdOf(item)) : [];
110	  return others.some((o) => {
111	    if (o.number === item.number) return false;
112	    if (!(hasLabel(o, EXECUTING) || hasLabel(o, AGENT))) return false;
113	    const conflicting = titleOf(o) === titleOf(item)
114	      || (upstreams.includes(taskIdOf(o)) && hasLabel(o, ORIGIN_SCHEDULE));
115	    return conflicting && o.claimId != null && o.claimId < myClaimId;
116	  });
117	}
118	
119	// The no-go outcome (DESIGN §6.4). A SCHEDULED item rolls — `Not-before` stamped
120	// with the task's next anchor, ready → blocked, the reason recorded — so the item
121	// itself carries "asked, declined, wakes at T" and the tick is a pure function of
122	// the clock and the issue list. An AD-HOC item has no next anchor to roll to, so
123	// it closes obsolete with the reason commented (a follow-up whose world settled on
124	// its own, S17).
125	export function noGoPlan(item, task, schedule, now, reason) {
126	  if (!hasLabel(item, ORIGIN_SCHEDULE)) {
127	    return { kind: 'close', outcome: OUTCOME_OBSOLETE, stateReason: 'not_planned', reason };
128	  }
129	  const until = nextAnchor(task.decl.frequency, schedule, now);
130	  return { kind: 'roll', until: until ? until.toISOString() : null, reason };
131	}
132	
133	// --- the shell ----------------------------------------------------------------
134	
135	const nowIso = () => new Date().toISOString();
136	
137	// One executor run. Injected seams keep the loop testable end to end without
138	// GitHub, prework subprocesses or an invocation endpoint.
139	export async function runExecutor({
140	  gh, repo, root, config, tasks, executorId, runUrl = null,
141	  maxItems = DEFAULT_MAX_ITEMS, now = () => new Date(),
142	  collectSignalsFor, runTaskPrework, invokeAgent, log = console.log,
143	}) {
144	  const api = await import('../github.mjs');
145	  const { listOpenWorkItems } = await import('./read.mjs');
146	  const schedule = config.taskScheduler;
147	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
148	  const taskAfter = (id) => byId.get(id)?.decl?.after ?? [];
149	  const done = [];
150	
151	  for (let n = 0; n < maxItems; n += 1) {
152	    const open = await listOpenWorkItems(gh, repo);
153	    const candidate = pickOrder(open, { taskAfter })[0];
154	    if (!candidate) break;
155	
156	    // --- claim: the verified lease ------------------------------------------
157	    await api.swapLabel(gh, repo, candidate.number, READY, EXECUTING);
158	    await api.comment(gh, repo, candidate.number, claimComment({
159	      executor: executorId, runUrl, at: nowIso(),
160	    }));
161	    const comments = await api.listComments(gh, repo, candidate.number);
162	    const winner = claimWinner(comments);
163	    if (!winner || !(winner.body ?? '').includes(`executor \`${executorId}\``)) {
164	      // The loser reverts nothing — the winner's labels already stand — and moves
165	      // on to a DIFFERENT item, read from live state on the next iteration.
166	      log(`- #${candidate.number}: another executor holds this episode's earliest claim — moving on`);
167	      continue;
168	    }
169	
170	    // --- post-claim re-verify (F15) -----------------------------------------
171	    const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
172	    if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter })) {
173	      await api.comment(gh, repo, candidate.number,
174	        `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
175	      await api.swapLabel(gh, repo, candidate.number, EXECUTING, READY);
176	      log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
177	      continue;
178	    }
179	
180	    const outcome = await executeItem({
181	      api, gh, repo, root, config, schedule, byId, item: candidate, executorId,
182	      now, collectSignalsFor, runTaskPrework, invokeAgent, log,
183	    });
184	    done.push({ issue: candidate.number, outcome });
185	  }
186	  return done;
187	}
188	
189	// The claim id of each live item, so the post-claim verify can compare episodes.
190	// One comment read per conflicting-looking item, not per item in the repo.
191	async function withClaimIds(api, gh, repo, items, selfNumber) {
192	  const out = [];
193	  for (const i of items) {
194	    if (i.number === selfNumber || !(hasLabel(i, EXECUTING) || hasLabel(i, AGENT))) { out.push(i); continue; }
195	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
196	    out.push({ ...i, claimId: winner?.id ?? null });
197	  }
198	  return out;
199	}
200	
201	// One claimed item, from validation through to a terminal state (or a hand-off).
202	async function executeItem({
203	  api, gh, repo, root, config, schedule, byId, item, executorId,
204	  now, collectSignalsFor, runTaskPrework, invokeAgent, log,
205	}) {
206	  const parsed = parseWorkItemTitle(item.title);
207	  const { taskPath } = parseWorkItemBody(item.body);
208	  const id = parsed ? `${parsed.pack}/${parsed.task}` : null;
209	  const task = id ? byId.get(id) : null;
210	
211	  // --- validate in code, before anything trusts the issue ------------------
212	  if (!parsed || !taskPath) {
213	    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
214	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.');
215	    return 'needs-human';
216	  }
217	  if (!task) {
218	    await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
219	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`);
220	    return 'obsolete';
221	  }
222	  if (task.taskPath !== taskPath) {
223	    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
224	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`);
225	    return 'needs-human';
226	  }
227	
228	  // --- the single precondition evaluation (DESIGN §6.4) --------------------
229	  const at = now();
230	  const signals = await collectSignalsFor(task, at);
231	  let verdict;
232	  try {
233	    verdict = task.decl.precondition(signals, config.packConfig?.[task.pack] ?? {}) ?? {};
234	  } catch (e) {
235	    verdict = { run: false, reason: `precondition threw: ${e.message}` };
236	  }
237	  if (verdict.run !== true) {
238	    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
239	    if (plan.kind === 'close') {
240	      await close(api, gh, repo, item.number, EXECUTING, OUTCOME_OBSOLETE, 'not_planned',
241	        `The precondition declined and this item has no anchor to roll to: ${plan.reason}`);
242	      return 'obsolete';
243	    }
244	    // The roll writes no comment — the `Not-before` bump IS the record, and an
245	    // hourly task that stays quiet would otherwise fill its own timeline (§5).
246	    await gh(`/repos/${repo}/issues/${item.number}`, {
247	      method: 'PATCH',
248	      body: { body: rollBody(item.body, plan.until, plan.reason, at.toISOString()) },
249	    });
250	    await api.swapLabel(gh, repo, item.number, EXECUTING, BLOCKED);
251	    log(`- #${item.number} ${id}: rolled to ${plan.until} — ${plan.reason}`);
252	    return 'rolled';
253	  }
254	
255	  // --- prework (unchanged contract), then converge or hand off -------------
256	  if (task.decl.prework) {
257	    const result = await runTaskPrework(task, { item, context: verdict.context ?? [] });
258	    if (!result.ok) {
259	      await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
260	        `Prework failed: ${result.why}${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
261	      return 'needs-human';
262	    }
263	    if (result.missingSecrets?.length) {
264	      await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
265	        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (remove \`needs-human\`, add \`task:ready\`).`);
266	      return 'needs-human';
267	    }
268	    if (!result.agentRequested) {
269	      const outcome = result.delivered?.length ? OUTCOME_DELIVERED : OUTCOME_DONE;
270	      await close(api, gh, repo, item.number, EXECUTING, outcome, 'completed',
271	        result.delivered?.length
272	          ? `Prework did this run's work and left a live artifact:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
273	          : 'Prework did this run\'s work; no agent was needed.');
274	      return outcome;
275	    }
276	    return handOff({ api, gh, repo, item, task, id, verdict, result, executorId, invokeAgent, config, log });
277	  }
278	
279	  // An agentless task with no prework does nothing (the contract forbids it).
280	  if (task.decl.agent_model === 'none') {
281	    await converge(api, gh, repo, item.number, EXECUTING, NEEDS_HUMAN,
282	      'This task is agentless but declares no prework, so there is nothing to run — a contract-forbidden shape that reached the queue.');
283	    return 'needs-human';
284	  }
285	  return handOff({ api, gh, repo, item, task, id, verdict, result: {}, executorId, invokeAgent, config, log });
286	}
287	
288	// The roll's body edit: stamp the next anchor and keep the last reason where an
289	// operator reads it. The reason REPLACES the previous one — the item is a status
290	// line, not a log; its timeline carries the history.
291	export function rollBody(body, until, reason, at) {
292	  const stamped = withNotBefore(body, until);
293	  return withSection(stamped, 'Last verdict', [
294	    `${at} — the precondition declined: ${reason}`,
295	    `Asked again at ${until}.`,
296	  ]);
297	}
298	
299	// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
300	// what lets this be as short as it is. The nonce goes on the item before the call
301	// and travels in the payload, so the session can prove the fire it arrived on is
302	// the hand-off this item recorded and stop if it is not.
303	async function handOff({ api, gh, repo, item, task, id, verdict, result, executorId, invokeAgent, config, log }) {
304	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
305	  let body = item.body;
306	  if (verdict.context?.length) body = withSection(body, 'Context', verdict.context);
307	  if (result.delivered?.length) body = withSection(body, 'Delivered by prework', result.delivered);
308	  if (result.reason) body = withSection(body, 'Why the agent is here', [result.reason]);
309	  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });
310	
311	  await api.swapLabel(gh, repo, item.number, EXECUTING, AGENT);
312	  await api.comment(gh, repo, item.number,
313	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
314	
315	  const invocation = await invokeAgent({ task, item, nonce, config });
316	  if (invocation.ok) {
317	    await api.comment(gh, repo, item.number,
318	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
319	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
320	    return 'agent';
321	  }
322	  if (invocation.answered) {
323	    // The endpoint refused, so no session exists and none will: a token, a URL or
324	    // a routine is wrong, and every future pick would be refused the same way.
325	    await converge(api, gh, repo, item.number, AGENT, NEEDS_HUMAN,
326	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (remove \`${NEEDS_HUMAN}\`, add \`${READY}\`).`);
327	    return 'needs-human';
328	  }
329	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
330	  // may have started a session. Re-queueing here is what would put two sessions on
331	  // one item, and converging to triage would kill a run that is very possibly
332	  // alive. So the item STAYS with the agent and says the outcome is unknown —
333	  // whichever way it went is then settled by a rule that already exists: a session
334	  // that started converges the item, and one that never did leaves the item silent
335	  // until the janitor's agent leash sweeps it to triage.
336	  await api.comment(gh, repo, item.number,
337	    `The agent invocation got no answer: ${invocation.error}\n\n`
338	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
339	    + `If a session did start it will converge this item; if it did not, the janitor's agent leash brings this item to \`${NEEDS_HUMAN}\` within a few hours.`);
340	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
341	  return 'unknown';
342	}
343	
344	// Every exit converges the item exactly once, with one comment saying what
345	// happened — the terminal-state discipline the incidents bought.
346	async function converge(api, gh, repo, number, from, to, body) {
347	  await api.comment(gh, repo, number, body);
348	  await api.swapLabel(gh, repo, number, from, to);
349	}
350	
351	async function close(api, gh, repo, number, from, outcome, stateReason, body) {
352	  await api.comment(gh, repo, number, body);
353	  await api.removeLabel(gh, repo, number, from);
354	  await api.addLabel(gh, repo, number, outcome);
355	  await api.closeIssue(gh, repo, number, stateReason);
356	}
357	
358	// --- CLI ----------------------------------------------------------------------
359	
360	async function main() {
361	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
362	  const { discoverTasks } = await import('../discover.mjs');
363	  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
364	  const { ensureLabels } = await import('../github.mjs');
365	  const { collectSignalsForTask } = await import('./signals.mjs');
366	  const { preworkRunner } = await import('./prework-run.mjs');
367	  const { agentInvoker } = await import('./invoke.mjs');
368	
369	  const root = process.cwd();
370	  const { repo, defaultBranch } = actionRepoContext();
371	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
372	  const config = loadConfig(root);
373	
374	  console.log('## Claudinite executor\n');
375	  if (isDormant(config)) {
376	    console.log('- this project declares itself dormant — nothing is picked up');
377	    return;
378	  }
379	
380	  const gh = makeGh();
381	  const { tasks, errors } = await discoverTasks(root, config);
382	  for (const e of errors) console.log(`! ${e.what}`);
383	  await ensureLabels(gh, repo, QUEUE_LABELS);
384	
385	  const runUrl = process.env.GITHUB_RUN_ID
386	    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
387	    : null;
388	
389	  const done = await runExecutor({
390	    gh, repo, root, config, tasks,
391	    executorId: process.env.CLAUDINITE_EXECUTOR_ID || `actions-${process.env.GITHUB_RUN_ID ?? 'local'}`,
392	    runUrl,
393	    maxItems: Number(process.env.CLAUDINITE_MAX_ITEMS) || DEFAULT_MAX_ITEMS,
394	    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
395	    runTaskPrework: preworkRunner({ root, repo, defaultBranch }),
396	    invokeAgent: agentInvoker({ repo, config }),
397	  });
398	
399	  console.log(done.length
400	    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
401	    : '- nothing ready to pick up');
402	}
403	
404	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
405	  main().catch((e) => { console.error(e); process.exit(1); });
406	}
407

